import { promises as fs } from "node:fs";
import path from "node:path";

import type { Locale } from "@/config/i18n";
import { contentPaths } from "./paths";

/**
 * Loading chapter MDX off disk.
 *
 * Server-only — everything here touches fs. Importing it from a client
 * component will fail at build, which is the behaviour we want.
 */

export interface TocEntry {
  /** Slug generated by rehype-slug, so it matches the rendered heading id. */
  id: string;
  text: string;
  depth: 2 | 3;
}

/** Has this chapter actually been written yet? */
export async function chapterExists(
  slug: string,
  locale: Locale = "en",
): Promise<boolean> {
  try {
    await fs.access(path.join(contentPaths.chapters(locale), `${slug}.mdx`));
    return true;
  } catch {
    return false;
  }
}

/** Slugs of every written chapter, for generateStaticParams. */
export async function listWrittenChapters(
  locale: Locale = "en",
): Promise<string[]> {
  try {
    const files = await fs.readdir(contentPaths.chapters(locale));
    return files
      .filter((f) => f.endsWith(".mdx"))
      .map((f) => f.replace(/\.mdx$/, ""));
  } catch {
    // Directory doesn't exist yet. Not an error — just nothing written.
    return [];
  }
}

async function readSource(
  slug: string,
  locale: Locale,
): Promise<string | null> {
  try {
    return await fs.readFile(
      path.join(contentPaths.chapters(locale), `${slug}.mdx`),
      "utf8",
    );
  } catch {
    return null;
  }
}

/**
 * Pulls h2/h3 out of the raw MDX for the table of contents.
 *
 * Reading the source rather than the rendered output because we need this on
 * the server before the component tree exists, and walking a compiled MDX AST
 * for three heading levels is more machinery than the job deserves.
 *
 * The slug rule has to stay in step with rehype-slug or the anchors won't
 * match. If someone swaps the slugger, this breaks quietly — worth a test
 * when the first real chapter lands.
 */
export async function getTableOfContents(
  slug: string,
  locale: Locale = "en",
): Promise<TocEntry[]> {
  const source = await readSource(slug, locale);
  return source ? extractHeadings(source) : [];
}

/** Same thing for anything under content/{locale}/pages. */
export async function getPageTableOfContents(
  slug: string,
  locale: Locale = "en",
): Promise<TocEntry[]> {
  try {
    const source = await fs.readFile(
      path.join(contentPaths.pages(locale), `${slug}.mdx`),
      "utf8",
    );
    return extractHeadings(source);
  } catch {
    return [];
  }
}

function extractHeadings(source: string): TocEntry[] {
  const entries: TocEntry[] = [];
  let insideFence = false;

  for (const line of source.split("\n")) {
    // Headings inside a code fence are code, not headings.
    if (line.trimStart().startsWith("```")) {
      insideFence = !insideFence;
      continue;
    }
    if (insideFence) continue;

    const match = /^(#{2,3})\s+(.+?)\s*$/.exec(line);
    if (!match?.[1] || !match[2]) continue;

    const text = match[2]
      .replace(/`/g, "") // inline code in headings
      .replace(/\*\*?/g, "") // bold/italic markers
      .trim();

    entries.push({
      id: slugifyHeading(text),
      text,
      depth: match[1].length as 2 | 3,
    });
  }

  return entries;
}

/** Mirrors github-slugger, which is what rehype-slug uses under the hood. */
function slugifyHeading(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s-]/gu, "")
    .trim()
    .replace(/\s+/g, "-");
}

/**
 * Loads the compiled MDX component for a chapter.
 *
 * The import path is built from a template literal, which means the bundler
 * has to be able to see the directory to generate the module map — hence the
 * literal `content/en/chapters` prefix rather than interpolating the locale
 * too. Add a branch per locale when Bangla routing lands.
 */
export async function loadChapterContent(slug: string, locale: Locale = "en") {
  // Check the file exists before importing rather than letting the import
  // throw. Exceptions as control flow is bad enough on its own, and it also
  // means an unwritten chapter doesn't produce a stack trace on every render.
  //
  // Note: while a chapters directory is empty, Turbopack logs a "can't resolve
  // <dynamic>.mdx" warning at build. It's harmless — there's no module map to
  // build yet — and it goes away as soon as the first chapter is written.
  if (!(await chapterExists(slug, locale))) return null;

  try {
    // One branch per locale, with the directory spelled out literally. The
    // bundler builds a module map from the static part of the path, so
    // interpolating the locale as well would leave it with nothing to scan
    // and every import would fail to resolve. A switch is the cost of that.
    const mod =
      locale === "bn"
        ? await import(`@/content/bn/chapters/${slug}.mdx`)
        : await import(`@/content/en/chapters/${slug}.mdx`);

    return {
      Content: mod.default as React.ComponentType,
      frontmatter: (mod.metadata ?? {}) as Record<string, unknown>,
    };
  } catch {
    return null;
  }
}
